  1965      dwarf_elf_object_access_internals_t *ep,int*errcode)
  1966  {
  1967      int res = 0;
  1968
  1969      if (ep->f_offsetsize == 32) {
  1970          res  = elf_load_sectheaders32(ep,ep->f_ehdr->ge_shoff,
  1971              ep->f_ehdr->ge_shentsize,
  1972              ep->f_ehdr->ge_shnum,errcode);
  1973      } else  if (ep->f_offsetsize == 64) {
  1974          res  = elf_load_sectheaders64(ep,ep->f_ehdr->ge_shoff,
  1975              ep->f_ehdr->ge_shentsize,
  1976              ep->f_ehdr->ge_shnum,errcode);
  1977      } else {
  1978          *errcode = DW_DLE_OFFSET_SIZE;
  1979          return DW_DLV_ERROR;
  1980      }
  1981      if (res != DW_DLV_OK) {
  1982          return res;
  1983      }
  1984      res  = _dwarf_elf_load_sectstrings(ep,
  1985          ep->f_ehdr->ge_shstrndx,errcode);
  1986      if (res != DW_DLV_OK) {
  1987          return res;
  1988      }
  1989      res  = _dwarf_elf_load_sect_namestring(ep,errcode);
  1990      if (res != DW_DLV_OK) {
  1991          return res;
  1992      }
  1993      res  = _dwarf_elf_find_sym_sections(ep,errcode);
  1994      if (res != DW_DLV_OK) {
  1995          return res;
  1996      }
